export default function PracticalGuideArticle({ articleKey }) {
  const article = articles[articleKey];
  if (!article) return null;
  const currentPath = `/blog/${article.slug}`;

  return (
    <div className="min-h-screen" dir="rtl">
      <GlobalNavbar />
      <main className="max-w-6xl mx-auto px-4 py-12 sm:py-20">
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          <article className="lg:col-span-2">
            <span className="text-xs text-primary/70 font-semibold bg-primary/8 px-3 py-1 rounded-full">{article.category}</span>
            <h1 className="text-3xl sm:text-4xl font-black text-foreground mt-4 leading-tight">{article.title}</h1>
            <p className="text-foreground/60 mt-3 text-lg leading-8">{article.description}</p>
            <img src={article.images[0].src} alt={article.images[0].alt} className="w-full h-64 sm:h-80 object-cover rounded-2xl my-8" loading="eager" referrerPolicy="no-referrer" />
            <p className="text-foreground/75 leading-8 mb-8">{article.intro}</p>

            {article.sections.map((section, index) => (
              <section key={section.title} className="glass-panel rounded-2xl p-6 mb-6">
                <h2 className="text-xl font-black text-primary mb-3">{section.title}</h2>
                {section.paragraphs.map((paragraph) => <p key={paragraph} className="text-sm text-foreground/70 leading-7 mb-3 last:mb-0">{paragraph}</p>)}
                {section.bullets && <ul className="list-disc list-inside space-y-2 mt-4 text-sm text-foreground/70">{section.bullets.map((item) => <li key={item}>{item}</li>)}</ul>}
                {(index === 1 || index === 3) && article.images[index === 1 ? 1 : 2] && (
                  <img src={article.images[index === 1 ? 1 : 2].src} alt={article.images[index === 1 ? 1 : 2].alt} className="w-full h-56 object-cover rounded-xl mt-5" loading="lazy" referrerPolicy="no-referrer" />
                )}
              </section>
            ))}

            <section className="glass-panel rounded-2xl p-6 mb-6">
              <h2 className="text-xl font-black text-primary mb-3">مطالب مکمل پیشنهادی</h2>
              <div className="flex flex-wrap gap-3">
                {article.related.map((item) => <Link key={item.href} href={item.href} className="text-sm text-primary hover:underline">{item.label}</Link>)}
              </div>
            </section>

            <section className="glass-panel rounded-2xl p-6 mb-6">
              <h2 className="text-xl font-black text-primary mb-3">منابع رسمی و تاریخ بازبینی</h2>
              <p className="text-sm text-foreground/70 leading-7 mb-3">اطلاعات این راهنما در ۱۸ شهریور ۱۴۰۵ برابر با ۹ سپتامبر ۲۰۲۶ بازبینی شده است. مقررات و رویه‌های اداری ممکن است تغییر کنند؛ پیش از اقدام، صفحه رسمی خدمت را دوباره بررسی کنید.</p>
              <ul className="space-y-2">{article.sources.map((source) => <li key={source.href}><a href={source.href} target="_blank" rel="noopener noreferrer" className="text-sm text-primary hover:underline">{source.label}</a></li>)}</ul>
            </section>

            <RelatedServices pageType={article.pageType} />
          </article>
          <PageSidebar tags={article.tags} currentPath={currentPath} serviceType={article.pageType} />
        </div>
      </main>
    </div>
  );
}
